pub fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>) {
    let x_len = x.len();
    let y_len = y.len();

    // Each output has y_len rows.
    let mut x_grid: Vec<Vec<f32>> = Vec::with_capacity(y_len);
    let mut y_grid: Vec<Vec<f32>> = Vec::with_capacity(y_len);

    for &yv in y.iter() {
        // X row is a copy of x: X[i][j] = x[j]
        x_grid.push(x.clone());

        // Y row is filled with y[i]: Y[i][j] = y[i]
        y_grid.push(vec![yv; x_len]);
    }

    (x_grid, y_grid)
}